// The library's icons: a 16px grid (8px for the small ones), 1.5px stroke, round caps; a few filled. Names are neutral.
// Icons drawn on a 24px grid carry a 2.25 stroke, so they draw at 1.5px like the rest.
export interface IconDefinition {
  viewBox: string
  /** The SVG's inner markup. */
  body: string
  /** Stroke width; filled icons have none. */
  stroke?: number
  cap?: 'round'
  join?: 'round'
  filled?: boolean
}

const s = (viewBox: string, body: string, stroke = 1.5, join = true): IconDefinition => ({
  viewBox,
  body,
  stroke,
  cap: 'round',
  join: join ? 'round' : undefined
})
const f = (viewBox: string, body: string): IconDefinition => ({ viewBox, body, filled: true })
const p = (d: string) => `<path d="${d}"/>`

